  api.exporter({
    id: 'example-csv',
    label: 'Table as CSV',
    extension: '.csv',
    from: '.table.json',
    export(_name, text) {
      const t = JSON.parse(text) as { columns: { id: string }[]; rows: Record<string, unknown>[] };
      const cols = t.columns.map((c) => c.id);
      return [cols.join(','), ...t.rows.map((r) => cols.map((c) => String(r[c] ?? '')).join(','))].join('\n');
    },
  }),
);

